use vstd::*;

verus! {

    /// Returns an index `m` in the slice `a` at or after `i` such that
    /// `a[m]` is the minimum of all `a[k]` for `k in [i, a.len())`.
    fn look_for_min(a: &[int], i: usize) -> usize
        requires
            // start index is valid
            i < a.len(),
        ensures
            // result is within the suffix starting at i
            i <= result && result < a.len(),
        ensures
            // a[result] is a minimum among all a[k] for k in [i, a.len())
            forall |k: usize|
                i <= k && k < a.len() ==> a[result] <= a[k]
    {
        // Initialize m to i and scan from j = i+1 .. a.len()
        let mut m: usize = i;
        let mut j: usize = i + 1;

        // Loop invariant maintains that m is the index of a minimum
        // element seen so far in the range [i, j).
        while j < a.len()
            invariant
                i <= m && m < a.len(),
            invariant
                i <= j && j <= a.len(),
            invariant
                forall |k: usize|
                    i <= k && k < j ==> a[m] <= a[k],
            decreases
                a.len() - j
        {
            if a[j] < a[m] {
                m = j;
            }
            j += 1;
        }

        // When the loop exits, j == a.len(), so m is the minimum in [i, a.len())
        m
    }

}